package com.digitalhealth.dto;
import com.digitalhealth.model.Role; import jakarta.validation.constraints.*;
public final class AuthDTO { private AuthDTO(){} public static class Register { @NotBlank @Size(min=3,max=120) public String username; @Email @NotBlank public String email; @NotBlank @Size(min=8,max=100) public String password; @NotNull public Role role=Role.WORKER; public Long workerId; } public static class Login { @NotBlank public String username; @NotBlank public String password; } public static class VerifyOtp { @NotBlank public String username; @NotBlank @Size(min=6,max=6) public String code; } public static class OtpResponse { public String message; public String username; public OtpResponse(String m,String u){message=m;username=u;} } public static class Response { public String token; public String username; public Role role; public Long workerId; public Response(String t,String u,Role r,Long w){token=t;username=u;role=r;workerId=w;} } }
